'use strict';
const D=window.ISKANDER_DATA;
const people=new Map(D.people.map(p=>[p.id,p]));
const works=new Map(D.works.map(w=>[w.id,w]));
const evidence=new Map(D.evidence.map(e=>[e.id,e]));
const aliasesByPerson=new Map(D.people.map(p=>[p.id,[]]));
for(const alias of D.aliases)(aliasesByPerson.get(alias.person_id)||[]).push(alias.name);
const searchTextByPerson=new Map(D.people.map(p=>[p.id,[p.canonical_name,p.description,...(aliasesByPerson.get(p.id)||[])].join(' ').toLocaleLowerCase('ru')]));
const placeLayout={east_prussia:[10,19],novgorod:[23,7],moscow:[36,8],ivanovo:[50,8],prayer_tree:[61,11],sabida:[72,12],bashkapsar:[88,17],sour_waters:[93,8],big_house:[62,21],chegem:[72,24],masha_yard:[52,25],adamyr_house:[94,27],dzhgerda:[84,29],chegem_spring:[64,33],ankhara:[93,39],estonka:[58,41],kodor_river:[77,40],anastasovka:[67,49],kengursk:[88,50],suburb:[52,51],government_house:[34,56],atary:[70,60],garden:[58,61],mukhus:[45,62],naa:[87,64],water_station:[18,69],chlou:[77,70],abkhaz_wall:[63,73],sandro_city_home:[42,73],amra:[30,76],sinop:[53,76],seaside_coffeehouse:[39,85],batum:[81,88],ship:[58,91],iran:[92,86]};
const semanticRelations=D.relations.filter(r=>r.type!=='co_occurs');
const appearancesByPerson=new Map(D.people.map(p=>[p.id,[]]));
const appearancesByWork=new Map(D.works.map(w=>[w.id,[]]));
for(const appearance of D.appearances){(appearancesByPerson.get(appearance.person_id)||[]).push(appearance);(appearancesByWork.get(appearance.work_id)||[]).push(appearance);}
const childrenByWork=new Map(D.works.map(w=>[w.id,[]]));
for(const work of D.works)if(work.parent_id&&childrenByWork.has(work.parent_id))childrenByWork.get(work.parent_id).push(work);
const workDescendantsCache=new Map;
function workDescendants(id){if(workDescendantsCache.has(id))return workDescendantsCache.get(id);const ids=new Set([id]);for(const child of childrenByWork.get(id)||[])for(const childId of workDescendants(child.id))ids.add(childId);workDescendantsCache.set(id,ids);return ids;}
function parseVolumeScope(value){const match=/^volume:(.+):(\d+)$/.exec(value||'');if(!match||!works.has(match[1]))return null;const volume=Number(match[2]);return (childrenByWork.get(match[1])||[]).some(w=>w.volume===volume)?{rootId:match[1],volume}:null;}
function scopeWorkIds(value){if(value==='all')return null;if(works.has(value))return workDescendants(value);const parsed=parseVolumeScope(value);return parsed?workDescendants(parsed.rootId):null;}
const evidenceWork=new Map(D.evidence.map(e=>[e.id,e.work_id]));
const relationWorks=new Map(semanticRelations.map(r=>[r.id,new Set((r.evidence||[]).map(id=>evidenceWork.get(id)).filter(Boolean))]));
const labels={graph:'Карта связей',people:'Персонажи',works:'Произведения',family:'Семьи',places:'Места'};
const roleNames={main:'Главный герой',secondary:'Второстепенный',episode:'Эпизод',mention:'Упоминание'};
const familyTypes=new Set(['parent','spouse','sibling','grandparent','cousin','avuncular']);
const state={view:'graph',person:'sandro',profile:'overview',relationMode:'all',graphPage:0,family:'sandro',place:'amra',work:null,scope:'all',workFilter:'pilot',peopleKind:'connected',peopleLimit:120,globalQuery:'',peopleQuery:'',workQuery:''};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const validViews=new Set(Object.keys(labels));
function routeUrl(route={}){const url=new URL(location.href);url.search='';url.hash='';const view=route.view||'graph';url.searchParams.set('view',view);if(route.person)url.searchParams.set('person',route.person);if(route.profile&&route.profile!=='overview')url.searchParams.set('profile',route.profile);if(route.page)url.searchParams.set('page',route.page);if(route.work)url.searchParams.set('work',route.work);if(route.family)url.searchParams.set('family',route.family);if(route.place)url.searchParams.set('place',route.place);if(route.kind)url.searchParams.set('kind',route.kind);if(route.filter)url.searchParams.set('filter',route.filter);if(route.wq)url.searchParams.set('wq',route.wq);const scope=route.scope??state.scope,relations=route.relations??state.relationMode;if(scope&&scope!=='all')url.searchParams.set('scope',scope);if(relations&&relations!=='all')url.searchParams.set('relations',relations);return url.pathname+url.search;}
const personUrl=id=>routeUrl({view:'graph',person:id});
const workUrl=id=>routeUrl({view:'works',work:id});
function readRoute(){const q=new URLSearchParams(location.search);const view=q.get('view');state.view=validViews.has(view)?view:'graph';const person=q.get('person');if(person&&people.has(person))state.person=person;state.profile=q.get('profile')==='appearances'?'appearances':'overview';const page=Number.parseInt(q.get('page')||'1',10);state.graphPage=Number.isFinite(page)&&page>0?page-1:0;const work=q.get('work');state.work=work&&works.has(work)?work:null;const family=q.get('family');if(family&&typeof families!=='undefined'&&families[family])state.family=family;const place=q.get('place');if(place&&D.places.some(p=>p.id===place))state.place=place;const kind=q.get('kind');state.peopleKind=['connected','all','historical','automatic'].includes(kind)?kind:'connected';const filter=q.get('filter');state.workFilter=['pilot','all','prose','poetry'].includes(filter)?filter:'pilot';const scope=q.get('scope'),legacyVolume=parseVolumeScope(scope);state.scope=scope&&works.has(scope)?scope:legacyVolume?.rootId||'all';const relations=q.get('relations');state.relationMode=['all','family','direct'].includes(relations)?relations:'all';state.globalQuery='';state.peopleQuery='';state.workQuery=q.get('wq')||'';}
function currentRouteUrl(){if(state.profile==='appearances')return routeUrl({view:'graph',person:state.person,profile:'appearances'});if(state.view==='graph')return routeUrl({view:'graph',person:state.person,page:state.graphPage+1});if(state.view==='works')return routeUrl({view:'works',work:state.work,filter:state.workFilter,wq:state.workQuery||undefined});if(state.view==='family')return routeUrl({view:'family',family:state.family});if(state.view==='places')return routeUrl({view:'places',place:state.place});if(state.view==='people')return routeUrl({view:'people',kind:state.peopleKind});return routeUrl({view:state.view});}
function syncUrl(replace=false){history[replace?'replaceState':'pushState'](null,'',currentRouteUrl());}
history.scrollRestoration='manual';
const scrollPageTop=()=>window.scrollTo({top:0,left:0,behavior:'auto'});
let searchRenderTimer=0,searchUrlTimer=0;
function scheduleSearchUrl(){clearTimeout(searchUrlTimer);searchUrlTimer=setTimeout(()=>syncUrl(true),350);}
function clearSearchTimers(){clearTimeout(searchRenderTimer);clearTimeout(searchUrlTimer);}
const personAnchor=(p,attrs='')=>`<a href="${esc(personUrl(p.id))}" data-person="${esc(p.id)}" data-view="graph" ${attrs}>${esc(p.canonical_name)}</a>`;
const workAnchor=(w,attrs='')=>`<a href="${esc(workUrl(w.id))}" data-work="${esc(w.id)}" ${attrs}>${esc(w.title)}</a>`;
const normalizeName=value=>String(value).trim().toLocaleLowerCase('ru');
const regexEscape=value=>value.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
const personNames=(()=>{const candidates=[];for(const p of D.people){candidates.push({name:p.canonical_name,id:p.id});for(const name of aliasesByPerson.get(p.id)||[]){if(/^\p{Lu}/u.test(name))candidates.push({name,id:p.id});}}const owners=new Map;for(const item of candidates){const key=normalizeName(item.name);if(key.length<3)continue;if(!owners.has(key))owners.set(key,new Set);owners.get(key).add(item.id);}return candidates.filter(item=>owners.get(normalizeName(item.name))?.size===1).sort((a,b)=>b.name.length-a.name.length);})();
const personNamePattern=personNames.length?new RegExp(`(?<![\\p{L}\\p{N}_])(?:${[...new Set(personNames.map(item=>regexEscape(item.name)))].join('|')})(?![\\p{L}\\p{N}_])`,'giu'):null;
const personByName=new Map(personNames.map(item=>[normalizeName(item.name),item.id]));
function linkPeople(value,exclude=[]){const text=String(value??'');if(!personNamePattern)return esc(text);refreshContext();const excluded=new Set(Array.isArray(exclude)?exclude:[exclude]);let html='',last=0;personNamePattern.lastIndex=0;for(const match of text.matchAll(personNamePattern)){const id=personByName.get(normalizeName(match[0]));if(!id||excluded.has(id)||!contextPeople.has(id))continue;html+=esc(text.slice(last,match.index))+`<a class="person-link" href="${esc(personUrl(id))}" data-person="${esc(id)}" data-view="graph">${esc(match[0])}</a>`;last=match.index+match[0].length;}return html+esc(text.slice(last));}
const textWord=n=>n%10===1&&n%100!==11?'текст':n%10>=2&&n%10<=4&&!(n%100>=12&&n%100<=14)?'текста':'текстов';
const initials=name=>name.replace(/[«»()]/g,'').split(/[\s-]+/).filter(Boolean).slice(0,2).map(n=>n[0]).join('');
const quoteButton=(ids,label='Открыть цитату')=>`<button class="text-button" data-evidence="${esc(ids.join(','))}">${esc(label)}</button>`;
const other=(r,id)=>people.get(r.from_person===id?r.to_person:r.from_person);
let contextKey='',contextWorkIds=null,contextPeople=new Set,contextRelations=[],contextRelationsByPerson=new Map,contextConnectionCounts=new Map;
function relationMatchesMode(r){if(state.relationMode==='family')return familyTypes.has(r.type);if(state.relationMode==='direct')return r.status==='accepted'&&r.confidence==='explicit';return true;}
function refreshContext(){
    const key=`${state.scope}|${state.relationMode}`;if(key===contextKey)return;
    contextKey=key;contextWorkIds=scopeWorkIds(state.scope);
    const basePeople=new Set;
    if(!contextWorkIds)for(const p of D.people)basePeople.add(p.id);
    else for(const workId of contextWorkIds)for(const a of appearancesByWork.get(workId)||[])basePeople.add(a.person_id);
    const inScope=r=>!contextWorkIds||[...(relationWorks.get(r.id)||[])].some(id=>contextWorkIds.has(id));
    const scopedRelations=semanticRelations.filter(r=>r.status!=='rejected'&&inScope(r));
    contextRelations=scopedRelations.filter(relationMatchesMode);
    if(state.relationMode==='all')contextPeople=basePeople;
    else{contextPeople=new Set;for(const r of contextRelations){if(basePeople.has(r.from_person))contextPeople.add(r.from_person);if(basePeople.has(r.to_person))contextPeople.add(r.to_person);}}
    contextRelationsByPerson=new Map([...contextPeople].map(id=>[id,[]]));
    for(const r of contextRelations){if(contextPeople.has(r.from_person)&&contextPeople.has(r.to_person)){(contextRelationsByPerson.get(r.from_person)||[]).push(r);(contextRelationsByPerson.get(r.to_person)||[]).push(r);}}
    contextConnectionCounts=new Map([...contextPeople].map(id=>[id,new Set((contextRelationsByPerson.get(id)||[]).map(r=>r.from_person===id?r.to_person:r.from_person)).size]));
}
const getRelations=id=>{refreshContext();return [...(contextRelationsByPerson.get(id)||[])].sort((a,b)=>connectionCount(other(b,id)?.id)-connectionCount(other(a,id)?.id));};
const visibleByRule=p=>getRelations(p.id).some(r=>other(r,p.id)?.id!=='narrator');
function relationRole(r,centerId){
    if(!centerId||!familyTypes.has(r.type))return r.label;
    const forward=r.from_person===centerId,label=r.label.toLocaleLowerCase('ru');
    if(r.type==='parent'){
        if(forward){if(label.includes('телён'))return 'Телёнок';if(label.includes('доч'))return 'Дочь';if(label.includes('сын'))return 'Сын';return 'Ребёнок';}
        if(label.startsWith('мать'))return 'Мать';if(label.startsWith('отец'))return 'Отец';if(label.startsWith('корова'))return 'Мать';return 'Родитель';
    }
    if(r.type==='grandparent'){
        if(forward)return label.includes('внучк')?'Внучка':'Внук';
        return label.startsWith('бабуш')?'Бабушка':'Дед';
    }
    if(r.type==='avuncular'){
        if(forward)return label.includes('племянниц')?'Племянница':'Племянник';
        return label.startsWith('тёт')?'Тётя':'Дядя';
    }
    if(r.type==='sibling'){
        if(label.includes('брат')&&label.includes('сестр')){
            const sisterFirst=label.indexOf('сестр')<label.indexOf('брат');
            return forward?(sisterFirst?'Брат':'Сестра'):(sisterFirst?'Сестра':'Брат');
        }
        if(label.includes('сёстр')||label.includes('сестр'))return 'Сестра';
        if(label.includes('брат'))return 'Брат';
        return 'Брат или сестра';
    }
    if(r.type==='cousin'){
        if(label.includes('брат')&&label.includes('сестр')){
            const sisterFirst=label.indexOf('сестр')<label.indexOf('брат');
            return forward?(sisterFirst?'Двоюродный брат':'Двоюродная сестра'):(sisterFirst?'Двоюродная сестра':'Двоюродный брат');
        }
        if(label.includes('сёстр')||label.includes('сестр'))return 'Двоюродная сестра';
        if(label.includes('брат'))return label.includes('троюрод')?'Троюродный брат':'Двоюродный брат';
        return 'Двоюродный родственник';
    }
    if(r.type==='spouse'){
        const target=other(r,centerId),targetText=`${target?.canonical_name||''} ${target?.description||''}`.toLocaleLowerCase('ru');
        if(/(^|\s)жена(\s|$)/.test(targetText))return 'Жена';
        if(/(^|\s)муж(\s|$)/.test(targetText))return 'Муж';
        if(label.startsWith('жена'))return forward?'Муж':'Жена';
        if(label.startsWith('муж')||label.startsWith('первый муж')||label.startsWith('второй муж'))return forward?'Жена':'Муж';
        return 'Супруг или супруга';
    }
    return r.label;
}
const connectionCount=id=>{refreshContext();return contextConnectionCounts.get(id)||0;};
const personSearchRank=(p,query)=>{if(!query)return 0;const name=normalizeName(p.canonical_name),aliases=(aliasesByPerson.get(p.id)||[]).map(normalizeName);if(name===query||aliases.includes(query))return 0;if(name.startsWith(query)||aliases.some(a=>a.startsWith(query)))return 1;if(name.includes(query)||aliases.some(a=>a.includes(query)))return 2;return 3;};
const byConnections=(a,b)=>connectionCount(b.id)-connectionCount(a.id)||a.canonical_name.localeCompare(b.canonical_name,'ru');
const scopedAppearances=id=>(appearancesByPerson.get(id)||[]).filter(a=>!contextWorkIds||contextWorkIds.has(a.work_id));
function defaultPersonForContext(){refreshContext();const preferred=state.scope==='work_detstvo_chika'?'chik':state.scope==='work_sandro_iz_chegema'?'sandro':null;if(preferred&&contextPeople.has(preferred))return people.get(preferred);return [...contextPeople].map(id=>people.get(id)).sort(byConnections)[0]||people.get('sandro')||D.people[0];}
function ensurePersonInContext(){refreshContext();if(!contextPeople.size){state.profile='overview';return;}if(!contextPeople.has(state.person)){state.person=defaultPersonForContext().id;state.graphPage=0;state.profile='overview';}}
function title(heading,description,eyebrow='ЛЮДИ И ИСТОРИИ'){refreshContext();const workCount=contextWorkIds?contextWorkIds.size:(D.meta.automatic_work_count||D.meta.pilot_count);return `<div class="title-row"><div><span class="eyebrow">${eyebrow}</span><h1>${heading}</h1><p class="subtitle">${description}</p></div><div class="stats"><div class="stat"><b>${contextPeople.size}</b><span>персонажей</span></div><div class="stat"><b>${contextRelations.length}</b><span>связей</span></div><div class="stat"><b>${workCount}</b><span>текстов в контексте</span></div></div></div>`;}
function profile(id){const p=people.get(id);const appearances=scopedAppearances(id);const aliases=[...new Set(aliasesByPerson.get(id)||[])].filter(n=>n!==p.canonical_name);const automatic=p.id.startsWith('bulk_');const scopedEvidence=(p.evidence||[]).filter(eid=>!contextWorkIds||contextWorkIds.has(evidenceWork.get(eid)));return `<aside class="panel person-card"><div class="portrait">${esc(initials(p.canonical_name))}</div><span class="eyebrow">${automatic?'УПОМИНАНИЕ В ТЕКСТЕ':p.kind==='historical'?'ИСТОРИЧЕСКОЕ ЛИЦО':p.kind==='narrator'?'РАССКАЗЧИК':p.kind==='animal'?'ЖИВОТНОЕ':'ПЕРСОНАЖ'}</span><h2>${esc(p.canonical_name)}</h2><span class="tag ${automatic?'amber':'green'}">${appearances.length} ${textWord(appearances.length)}</span><p class="description">${linkPeople(p.description,id)}</p>${scopedEvidence.length?quoteButton(scopedEvidence,'Цитаты из книг ↗'):''}${aliases.length?`<div class="profile-sep"></div><p class="mini-heading">Другие имена</p><p class="subtitle">${aliases.map(esc).join(' · ')}</p>`:''}<div class="profile-sep"></div><p class="mini-heading">Появляется в выбранном контексте</p>${appearances.map(a=>`<div class="work-item">${workAnchor(works.get(a.work_id))}<div class="work-meta">${roleNames[a.role]} · том ${works.get(a.work_id).volume}</div></div>`).join('')||'<p class="small-count">Нет появлений в выбранном контексте.</p>'}<div class="profile-actions"><a class="button primary" href="${esc(routeUrl({view:'graph',person:id,profile:'appearances'}))}" data-profile="appearances" data-person="${id}">Все появления ↗</a><a class="button" href="${esc(personUrl(id))}" data-person="${id}" data-view="graph">Связи</a></div></aside>`;}
function graph(id){const relations=getRelations(id);const allNeighbors=[...new Set(relations.map(r=>other(r,id).id))];const pageSize=window.innerWidth<1000?8:12;const pages=Math.max(1,Math.ceil(allNeighbors.length/pageSize));state.graphPage%=pages;let neighbors=allNeighbors.slice(state.graphPage*pageSize,(state.graphPage+1)*pageSize);const width=820,height=650,cx=410,cy=302;const p=people.get(id);const positions=new Map([[id,{x:cx,y:cy}]]);neighbors.forEach((n,i)=>{const angle=-Math.PI/2+i*Math.PI*2/neighbors.length;positions.set(n,{x:cx+270*Math.cos(angle),y:cy+235*Math.sin(angle)});});let edges='';for(const n of neighbors){const r=relations.find(r=>other(r,id).id===n);const pt=positions.get(n);edges+=`<g class="graph-edge"><line x1="${cx}" y1="${cy}" x2="${pt.x}" y2="${pt.y}" class="graph-line ${familyTypes.has(r.type)?'family':''} ${r.status==='reported'?'reported':''}"/><title>${esc(relationRole(r,id))}</title></g>`;}
let nodes=[id,...neighbors].map(n=>{const pt=positions.get(n),person=people.get(n),center=n===id;const words=person.canonical_name.split(' ');let lines=words.length>2?[words.slice(0,2).join(' '),words.slice(2).join(' ')]:[person.canonical_name];return `<g class="graph-node ${center?'center':''}" tabindex="0" role="button" aria-label="Открыть ${esc(person.canonical_name)}" data-person="${n}" transform="translate(${pt.x},${pt.y})"><title>${esc(person.canonical_name)}</title><circle r="${center?48:27}"/><text class="graph-initial" text-anchor="middle" dominant-baseline="central">${esc(initials(person.canonical_name))}</text>${lines.map((line,i)=>`<text class="graph-name" text-anchor="middle" y="${(center?73:48)+i*19}">${esc(line)}</text>`).join('')}</g>`;}).join('');const pagination=pages>1?`<nav class="graph-pagination" aria-label="Страницы связей"><button class="button" data-graph-page="${(state.graphPage-1+pages)%pages}" aria-label="Предыдущая страница связей">←</button><span>Страница ${state.graphPage+1} из ${pages}</span><button class="button" data-graph-page="${(state.graphPage+1)%pages}" aria-label="Следующая страница связей">→</button></nav>`:'';const home=defaultPersonForContext();return `<div class="panel"><div class="graph-head"><span class="panel-label">Окружение · ${esc(p.canonical_name)}</span><button class="button" data-person="${home.id}" title="Главный герой выбранного контекста">К главному герою</button></div><div class="graph-stage"><svg viewBox="0 0 ${width} ${height}" role="group" aria-label="Граф связей ${esc(p.canonical_name)}">${edges}${nodes}</svg>${!neighbors.length?'<p class="empty">Связей с этим фильтром пока нет.</p>':''}<span class="graph-note">${neighbors.length} из ${allNeighbors.length} связей · выберите героя</span></div><div class="legend">${pagination}<span><i></i>Социальная связь</span><span><i class="family"></i>Родство</span><span><i class="reported"></i>По словам героя</span></div></div>`;}
function relationRows(relations,id=null){return `<div class="rel-list">${relations.map(r=>{const a=people.get(r.from_person),b=people.get(r.to_person);const target=id?other(r,id):b;return `<article class="rel-row"><span class="tiny-portrait">${esc(initials(target.canonical_name))}</span><div>${id?personAnchor(target):personAnchor(a)+' → '+personAnchor(b)}<small>${linkPeople(relationRole(r,id))}${r.status==='reported'?' · со слов героя':''}</small>${r.status==='rejected'?'<span class="tag red">Связь опровергнута</span>':''}</div>${quoteButton(r.evidence,'Цитата ↗')}</article>`;}).join('')||'<p class="empty">Для этого персонажа пока нет связей.</p>'}</div>`;}
function graphPage(){refreshContext();if(!contextPeople.size)return title('Карта связей','Выберите героя — и пройдите по его семье, знакомым и книгам.')+`<div class="panel empty"><p>В выбранном произведении нет персонажей, подходящих под этот тип связей.</p><button class="button" data-relation-all>Показать все связи</button></div>`;const rels=getRelations(state.person);return title('Карта связей','Выберите героя — и пройдите по его семье, знакомым и книгам.')+`<div class="workspace">${graph(state.person)}${profile(state.person)}</div><h2 class="section-title">Что их связывает <span class="small-count">${rels.length}</span></h2><div class="relation-columns">${relationRows(rels,state.person)}</div>`;}
function personTiles(list){return list.map(p=>{const count=scopedAppearances(p.id).length;return `<article class="entity-tile"><span class="tiny-portrait" style="margin-bottom:16px">${esc(initials(p.canonical_name))}</span><h3>${personAnchor(p)}</h3><p>${linkPeople(p.description,p.id)}</p><span class="source-count">${count} ${count===1?'текст':'текста'} · ${getRelations(p.id).length} связей</span></article>`;}).join('');}
function peopleList(){refreshContext();const query=normalizeName(state.globalQuery);return [...contextPeople].map(id=>people.get(id)).filter(p=>state.peopleKind==='all'||state.peopleKind==='historical'&&p.kind==='historical'||state.peopleKind==='automatic'&&p.id.startsWith('bulk_')||state.peopleKind==='connected'&&visibleByRule(p)).filter(p=>!query||searchTextByPerson.get(p.id).includes(query)).sort((a,b)=>personSearchRank(a,query)-personSearchRank(b,query)||byConnections(a,b));}
function peopleResults(){const list=peopleList(),limited=list.slice(0,state.peopleLimit);return `<p class="small-count people-count">Найдено ${list.length}${limited.length<list.length?` · показаны первые ${limited.length}`:''}</p><div class="collection-grid">${personTiles(limited)}</div>${limited.length<list.length?`<div class="load-more"><button class="button" data-people-more>Показать ещё ${Math.min(120,list.length-limited.length)}</button></div>`:''}${list.length?'':'<div class="panel empty">Персонажи не найдены. Попробуйте имя, прозвище или слово из описания.</div>'}`;}
function peoplePage(){refreshContext();const connected=[...contextPeople].map(id=>people.get(id)).filter(visibleByRule);return title('Люди литературного мира','Главные, повторяющиеся и связанные между собой герои книг.')+`<div class="people-filterbar"><div class="filters"><button class="button ${state.peopleKind==='connected'?'active':''}" data-people-kind="connected">Связанные · ${connected.length}</button><button class="button ${state.peopleKind==='all'?'active':''}" data-people-kind="all">Все · ${contextPeople.size}</button><button class="button ${state.peopleKind==='historical'?'active':''}" data-people-kind="historical">Исторические лица</button><button class="button ${state.peopleKind==='automatic'?'active':''}" data-people-kind="automatic">Другие упоминания</button></div></div><div id="people-results">${peopleResults()}</div>`;}
function appearancesPage(){const p=people.get(state.person),confirmed=scopedAppearances(p.id);const hits=D.corpusHits.filter(h=>h.person_id===p.id&&(!contextWorkIds||contextWorkIds.has(h.work_id))).sort((a,b)=>b.count-a.count);return title(`Где появляется ${esc(p.canonical_name)}`,'Произведения и фрагменты в выбранном контексте.','ПУТЬ ГЕРОЯ ПО КНИГАМ')+`<div class="reading-layout"><div><h2 class="section-title" style="margin-top:0">Появления · ${confirmed.length}</h2><div class="panel content-pad">${confirmed.map(a=>{const w=works.get(a.work_id);return `<article class="hit-row"><span class="tag green">${roleNames[a.role]}</span><h3 style="margin-top:12px"><button data-work="${w.id}">${esc(w.title)}</button></h3><p>Том ${w.volume} · ${w.kind==='novel_chapter'?'Глава романа':kindNames[w.kind]||'Произведение'}</p>${quoteButton(a.evidence,'Открыть фрагмент ↗')}</article>`;}).join('')}</div>${hits.length?`<h2 class="section-title">Другие возможные упоминания · ${hits.length}</h2><p class="subtitle" style="margin-bottom:18px">Имя встречается в тексте, но контекста может быть недостаточно для уверенного отождествления.</p><div class="panel content-pad">${hits.map(h=>{const w=works.get(h.work_id);return `<article class="hit-row"><h3><button data-work="${w.id}">${esc(w.title)}</button></h3><span class="tag amber">Возможное упоминание</span> <span class="small-count">Том ${w.volume}</span><p>${esc(evidence.get(h.evidence_id).quote)}</p>${quoteButton([h.evidence_id],'Открыть фрагмент ↗')}</article>`;}).join('')}</div>`:''}</div>${profile(p.id)}</div>`;}
const kindNames={novel:'Роман',cycle:'Цикл',work:'Произведение',cycle_story:'Рассказ цикла',novel_chapter:'Глава романа',work_part:'Часть произведения',poem:'Стихотворение / баллада',long_poem:'Поэма',epigram:'Эпиграмма / шутка',translation:'Перевод',essay:'Эссе',notes:'Записки'};
function workTable(query=''){refreshContext();const q=query.toLocaleLowerCase('ru');const rows=D.works.filter(w=>(!contextWorkIds||contextWorkIds.has(w.id))&&(state.workFilter==='all'||state.workFilter==='pilot'&&(w.pilot||w.automatic)||state.workFilter==='prose'&&['novel','cycle','work','cycle_story','novel_chapter','work_part'].includes(w.kind)||state.workFilter==='poetry'&&['poem','long_poem','epigram','translation'].includes(w.kind))&&w.title.toLocaleLowerCase('ru').includes(q)).sort((a,b)=>(a.volume??0)-(b.volume??0)||a.title.localeCompare(b.title,'ru'));return `<p class="small-count">Найдено ${rows.length} произведений и частей.</p><div class="panel"><table class="work-table"><thead><tr><th class="number">Том</th><th>Название</th><th>В атласе</th></tr></thead><tbody>${rows.map(w=>`<tr><td class="number">${w.volume??'—'}</td><td>${workAnchor(w)}<div class="work-meta">${kindNames[w.kind]||w.kind}${w.parent_id?' · '+esc(works.get(w.parent_id)?.title):''}</div></td><td>${w.pilot?'<span class="tag green">Есть персонажи</span>':w.automatic?'<span class="tag amber">Есть упоминания</span>':'<span class="small-count">Текст в собрании</span>'}</td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">По этому запросу ничего не найдено.</div>'}</div>`;}
function worksPage(){if(state.work)return workPage(state.work);return title('Произведения','Десять томов, отдельные тексты и части больших историй.','СОБРАНИЕ ТЕКСТОВ')+`<div class="section-tools"><div class="section-search"><label for="work-search">Поиск в произведениях</label><input id="work-search" type="search" value="${esc(state.workQuery)}" placeholder="Название произведения…" autocomplete="off"></div><div class="filters">${[['pilot','С персонажами'],['all','Все · '+D.works.length],['prose','Проза'],['poetry','Поэзия и переводы']].map(([id,name])=>`<button class="button ${state.workFilter===id?'active':''}" data-work-filter="${id}">${name}</button>`).join('')}</div></div><div id="work-results">${workTable(state.workQuery)}</div>`;}
function workPage(id){const w=works.get(id);refreshContext();const appearances=(appearancesByWork.get(id)||[]).filter(a=>contextPeople.has(a.person_id));const children=childrenByWork.get(id)||[];const hits=D.corpusHits.filter(h=>h.work_id===id&&contextPeople.has(h.person_id));return `<button class="text-button" data-work-back style="margin-bottom:22px">← Все произведения</button>`+title(esc(w.title),`${w.volume?'Том '+w.volume+' · ':''}${kindNames[w.kind]||w.kind}`,'ПРОИЗВЕДЕНИЕ')+`<div class="panel content-pad">${appearances.length?`<h2 class="section-title" style="margin-top:0">Персонажи · ${appearances.length}</h2><div class="rel-list">${appearances.sort((a,b)=>Object.keys(roleNames).indexOf(a.role)-Object.keys(roleNames).indexOf(b.role)).map(a=>{const p=people.get(a.person_id);return `<article class="rel-row"><span class="tiny-portrait">${esc(initials(p.canonical_name))}</span><div><button data-person="${p.id}" data-view="graph">${esc(p.canonical_name)}</button><small>${roleNames[a.role]}</small></div>${quoteButton(a.evidence,'Фрагмент ↗')}</article>`;}).join('')}</div>`:`<p class="subtitle">${children.length?'Выберите одну из частей произведения.':'Персонажи этого текста пока не добавлены в атлас.'}</p>`}${children.length?`<h2 class="section-title">Части · ${children.length}</h2><div class="rel-list">${children.map(c=>`<div class="rel-row"><div><button data-work="${c.id}">${esc(c.title)}</button></div></div>`).join('')}</div>`:''}${hits.length?`<h2 class="section-title">Возможные упоминания</h2><p class="subtitle" style="margin-bottom:15px">Имя встречается в тексте, но может относиться к другому человеку.</p><div class="rel-list">${hits.map(h=>`<div class="rel-row"><div><button data-person="${h.person_id}" data-view="graph">${esc(people.get(h.person_id).canonical_name)}</button></div>${quoteButton([h.evidence_id],'Фрагмент ↗')}</div>`).join('')}</div>`:''}</div>`;}
const families={chik:{name:'Семья Чика',nodes:{chik_grandmother:[100,65],chik_aunt:[300,65],chik_uncle_riza:[520,65],chik_uncle_kolya:[700,65],chik_mother:[180,250],chik_father:[400,250],chik_older_brother:[90,420],chik:[310,420],chik_sister:[570,420]}},sandro:{name:'Семья Сандро',nodes:{father_sandro:[300,55],wife_habug:[520,55],brother_sandro:[100,225],isa:[300,225],sandro:[520,225],katya:[700,225],granddaughter:[100,410],tali:[610,410]}},katya_family:{name:'Семья тёти Кати',nodes:{katya_grandmother:[180,80],katya:[390,300],sandro:[650,300]}},kyzym:{name:'Семья Кязыма',nodes:{father_sandro:[170,65],wife_habug:[390,65],kyzym:[280,230],nutsa:[540,230],kyzym_son:[280,410],kyzym_daughter:[570,410]}},mahaz:{name:'Семья Махаза',nodes:{brother_sandro:[280,90],masha:[520,90],firuza:[220,330],lena_masha:[580,330]}},isa:{name:'Семья Исы',nodes:{isa:[280,90],isa_wife:[520,90],adgur:[180,330],zarifa:[400,330],katusha:[620,330]}},tali:{name:'Семья Тали',nodes:{sandro:[230,80],katya:[470,80],tali:[350,270],bagrat:[610,270]}},shashiko:{name:'Семья Щащико',nodes:{shashiko_mother:[220,70],shashiko_brother:[220,250],shashiko:[450,250],shashiko_wife:[650,250],shashiko_son:[550,420]}},narrator:{name:'Семья рассказчика',nodes:{chik_mother:[270,100],narrator_father:[530,100],narrator:[400,340]}},lakoba:{name:'Семья Лакобы',nodes:{lakoba:[400,90],sarya_lakoba:[620,90],rauf_lakoba:[400,330]}},tobacconist:{name:'Семья табачника',nodes:{tab_mother:[500,60],tobacconist:[270,225],tab_wife:[500,225],tab_son:[260,410],tab_daughter:[520,410]}},lamba:{name:'Братья Ламба',nodes:{lamba_father:[400,80],lamba_elder:[220,300],lamba_younger:[580,300]}},shop:{name:'Семья лавочника',nodes:{shopkeeper:[270,100],shop_wife:[530,100],shop_son:[400,330]}},girl:{name:'Семья девочки',nodes:{girl_father:[260,100],girl_mother:[540,100],girl_amra:[400,330]}},german_sisters:{name:'Сёстры из Восточной Пруссии',nodes:{german_uncle:[400,70],german_katrin:[250,300],greta:[550,300]}},vakhtang_family:{name:'Семья Вахтанга',nodes:{vakhtang_father:[270,100],vakhtang_mother:[530,100],vakhtang:[400,340]}},adamyr_family:{name:'Семья Адамыра',nodes:{adamyr_mother:[400,90],adamyr:[400,330]}}};
function familyPage(){const f=families[state.family];const ids=Object.keys(f.nodes);const rels=D.relations.filter(r=>familyTypes.has(r.type)&&r.status!=='rejected'&&r.confidence!=='uncertain'&&ids.includes(r.from_person)&&ids.includes(r.to_person));let svg=rels.map(r=>{const a=f.nodes[r.from_person],b=f.nodes[r.to_person];return `<g><line class="family-line" x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}"/><text class="graph-edge-label" text-anchor="middle" x="${(a[0]+b[0])/2}" y="${(a[1]+b[1])/2-9}">${esc(r.label.toLocaleLowerCase('ru'))}</text></g>`;}).join('');svg+=ids.map(id=>{const [x,y]=f.nodes[id];const p=people.get(id);const words=p.canonical_name.split(' '),lines=words.length>2?[words.slice(0,2).join(' '),words.slice(2).join(' ')]:[p.canonical_name];return `<g class="graph-node" role="button" tabindex="0" data-person="${id}" data-view="graph" aria-label="Открыть ${esc(p.canonical_name)}" transform="translate(${x},${y})"><rect class="family-box" x="-105" y="-35" rx="7" width="210" height="70"/>${lines.map((line,i)=>`<text class="family-name" text-anchor="middle" y="${lines.length===1?5:-3+i*21}">${esc(line)}</text>`).join('')}</g>`;}).join('');return title('Семьи и родство','Родственные линии героев и переходы между поколениями.','ПОКОЛЕНИЯ')+`<div class="family-selector">${Object.entries(families).map(([id,f])=>`<button class="button ${state.family===id?'active':''}" data-family="${id}">${f.name}</button>`).join('')}</div><div class="panel"><div class="graph-head"><span class="panel-label">${f.name}</span></div><div class="family-scroll"><svg class="family-svg" viewBox="0 0 800 490" role="group" aria-label="${f.name}">${svg}</svg></div></div>${state.family==='chik'?'<div class="notice">Некоторые родственники Чика не названы по имени и поэтому обозначены семейной ролью.</div>':''}${state.family==='sandro'?'<div class="notice">Щащико не показан в дереве: известно лишь о дальнем родстве с Сандро, но его точная линия не названа.</div>':''}${state.family==='katya_family'?'<div class="notice">О происхождении бабушки Кати рассказывает Аслан.</div>':''}${state.family==='girl'?'<div class="notice">«Дедушка Ленин» — обращение, а не кровное родство.</div>':''}<h2 class="section-title">Связи семьи</h2>${relationRows(rels)}`;}
function placesPage(){const p=D.places.find(p=>p.id===state.place);const links=D.personPlaces.filter(l=>l.place_id===p.id);return title('Места, к которым ведут истории','Север — сверху, запад — слева; расстояния между местами условны.','ГЕОГРАФИЯ ПОВЕСТВОВАНИЯ')+`<div class="workspace"><div class="panel map-panel"><div class="map-stage" aria-label="Схема мест, ориентированная по сторонам света"><span class="map-compass" aria-hidden="true">С ↑</span><span class="sea-label" aria-hidden="true">Чёрное море</span>${D.places.map(place=>{const [x,y]=placeLayout[place.id]||[place.x,place.y];return `<button class="place-pin ${place.id===p.id?'active':''}" style="left:${x}%;top:${y}%" data-place="${place.id}">${esc(place.name)}<span>${esc(place.kind==='country'?'Страна':place.kind)}</span></button>`;}).join('')}</div><p class="map-caption">Ориентация по сторонам света сохранена; расстояния и масштаб условны</p></div><aside class="panel person-card"><span class="eyebrow">${esc((p.kind==='country'?'Страна':p.kind).toUpperCase())}</span><h2>${esc(p.name)}</h2><p class="description">${linkPeople(p.description)}</p>${quoteButton(p.evidence,'Место в тексте ↗')}<div class="profile-sep"></div><p class="mini-heading">Кто здесь появляется</p>${links.map(l=>`<div class="work-item"><button data-person="${l.person_id}" data-view="graph">${esc(people.get(l.person_id).canonical_name)}</button><div class="work-meta">${linkPeople(l.label)} · ${quoteButton([l.evidence_id],'цитата')}</div></div>`).join('')}</aside></div>`;}
const proseKinds=new Set(['novel','cycle','work','cycle_story','novel_chapter','work_part']);
const majorStandaloneTitles=['Созвездие Козлотура','Школьный вальс, или энергия стыда','Морской скорпион','Софичка','Человек и его окрестности','Кролики и удавы'];
const majorStandaloneOrder=new Map(majorStandaloneTitles.map((title,index)=>[title,index]));
const scopeLabel=()=>state.scope==='all'?'Мир Искандера':works.get(state.scope)?.title||'Мир Искандера';
const scopeOption=(w,extra='')=>`<button class="scope-option ${state.scope===w.id?'active':''} ${extra}" data-scope="${w.id}" data-scope-option data-scope-name="${esc(normalizeName(w.title))}"><span>${esc(w.title)}</span></button>`;
function scopeTree(){
    const roots=D.works.filter(w=>!w.parent_id&&proseKinds.has(w.kind));
    const composites=roots.filter(w=>(childrenByWork.get(w.id)||[]).length).sort((a,b)=>{const order=['work_detstvo_chika','work_sandro_iz_chegema'];const ai=order.indexOf(a.id),bi=order.indexOf(b.id);return (ai<0?99:ai)-(bi<0?99:bi)||a.title.localeCompare(b.title,'ru');});
    const compositeHtml=composites.map(root=>{const children=childrenByWork.get(root.id)||[];return `<section class="scope-section" data-scope-group><div class="scope-parent">${scopeOption(root)}</div><details ${state.scope===root.id||children.some(w=>w.id===state.scope)?'open':''}><summary>Выбрать часть · ${children.length}</summary>${children.map(w=>scopeOption(w,'nested')).join('')}</details></section>`;}).join('');
    const standalone=roots.filter(w=>!(childrenByWork.get(w.id)||[]).length&&(appearancesByWork.get(w.id)||[]).length);
    const major=standalone.filter(w=>majorStandaloneOrder.has(w.title)).sort((a,b)=>majorStandaloneOrder.get(a.title)-majorStandaloneOrder.get(b.title));
    const stories=standalone.filter(w=>!majorStandaloneOrder.has(w.title)).sort((a,b)=>a.title.localeCompare(b.title,'ru'));
    const majorHtml=major.map(w=>scopeOption(w)).join('');
    const storiesHtml=stories.length?`<details class="scope-section" data-scope-group ${stories.some(w=>w.id===state.scope)?'open':''}><summary>Рассказы · ${stories.length}</summary>${stories.map(w=>scopeOption(w,'nested')).join('')}</details>`:'';
    const other=D.works.filter(w=>!w.parent_id&&!proseKinds.has(w.kind)&&(appearancesByWork.get(w.id)||[]).length).sort((a,b)=>(a.volume??0)-(b.volume??0)||a.title.localeCompare(b.title,'ru'));
    const otherHtml=other.length?`<details class="scope-section" data-scope-group><summary>Стихи, эссе и другие тексты · ${other.length}</summary>${other.map(w=>scopeOption(w,'nested')).join('')}</details>`:'';
    return `<button class="scope-option ${state.scope==='all'?'active':''}" data-scope="all" data-scope-option data-scope-name="мир искандера"><span>Мир Искандера</span><small>весь корпус</small></button><p class="scope-heading">Книги и циклы</p>${compositeHtml}${majorHtml}<p class="scope-heading">Другие тексты</p>${storiesHtml}${otherHtml}`;
}
function renderContextBar(){const bar=document.getElementById('contextbar');const visible=!['family','places'].includes(state.view);bar.hidden=!visible;if(!visible){bar.innerHTML='';return;}bar.innerHTML=`<div class="context-inner"><span class="context-caption">Показываем</span><details class="scope-picker"><summary><span class="context-kicker">Произведение</span><b>${esc(scopeLabel())}</b></summary><div class="scope-popover"><label class="scope-search"><span class="sr-only">Найти произведение для фильтра</span><input id="scope-search" type="search" placeholder="Найти произведение…" autocomplete="off"></label><div class="scope-tree">${scopeTree()}</div></div></details><label class="relation-picker"><span class="context-kicker">Персонажи</span><select id="relation-scope"><option value="all" ${state.relationMode==='all'?'selected':''}>Все связи</option><option value="family" ${state.relationMode==='family'?'selected':''}>Только родственники</option><option value="direct" ${state.relationMode==='direct'?'selected':''}>Только прямые связи</option></select></label>${state.scope!=='all'||state.relationMode!=='all'?'<button class="context-reset" data-context-reset>Сбросить</button>':''}</div>`;}
function currentLabel(){if(state.profile==='appearances')return `Появления · ${people.get(state.person).canonical_name}`;if(state.view==='graph')return `Карта · ${people.get(state.person).canonical_name}`;if(state.view==='works'&&state.work)return `Произведение · ${works.get(state.work).title}`;if(state.view==='family')return families[state.family].name;if(state.view==='places')return `Место · ${D.places.find(p=>p.id===state.place).name}`;return labels[state.view]||'Персонаж';}
function render(){const started=performance.now();refreshContext();const previousPerson=state.person;if(!['family','places'].includes(state.view))ensurePersonInContext();if(state.person!==previousPerson)syncUrl(true);const label=currentLabel();document.getElementById('current-view').textContent=label;document.querySelectorAll('[data-view].nav-item').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);b.setAttribute('aria-current',b.dataset.view===state.view?'page':'false');b.setAttribute('href',routeUrl({view:b.dataset.view}));});document.querySelectorAll('[data-nav-root]').forEach(link=>link.setAttribute('href',routeUrl({view:'graph'})));renderContextBar();const renderers={graph:graphPage,people:peoplePage,works:worksPage,family:familyPage,places:placesPage};document.getElementById('content').innerHTML=state.profile==='appearances'?appearancesPage():renderers[state.view]();const search=document.getElementById('search');search.value=state.globalQuery;search.placeholder=state.view==='people'?'Найти персонажа…':'Найти героя или произведение…';document.title=label+' — Мир Искандера';document.documentElement.dataset.lastRenderMs=(performance.now()-started).toFixed(1);}
function showEvidence(ids,heading='Цитаты из книг'){document.getElementById('evidence-title').textContent=heading;document.getElementById('evidence-content').innerHTML=[...new Set(ids)].map(id=>{const e=evidence.get(id);if(!e)return '';const w=works.get(e.work_id);return `<article class="quote-card"><span class="eyebrow">${w?.volume?'ТОМ '+w.volume:'ИЗ КНИГИ'}</span><h3>${esc(w?.title)}</h3><blockquote>${linkPeople(e.quote)}</blockquote></article>`;}).join('');const dialog=document.getElementById('evidence-dialog');if(!dialog.open)dialog.showModal();}
document.addEventListener('click',event=>{const button=event.target.closest('[data-person],[data-evidence],[data-close],[data-view],[data-work],[data-profile],[data-family],[data-place],[data-work-filter],[data-work-back],[data-people-kind],[data-people-more],[data-relation-all],[data-graph-page],[data-history-back],[data-history-forward],[data-scope],[data-context-reset]');if(!button)return;if(button.matches('a')&&(event.button!==0||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey))return;if(button.matches('a'))event.preventDefault();if(button.hasAttribute('data-history-back'))return history.back();if(button.hasAttribute('data-history-forward'))return history.forward();if(button.hasAttribute('data-close'))return document.getElementById('evidence-dialog').close();if(button.dataset.evidence)return showEvidence(button.dataset.evidence.split(','));clearSearchTimers();const primaryNavigation=button.classList.contains('nav-item')||button.hasAttribute('data-nav-root');const fromGlobalSearch=Boolean(button.closest('#search-results'));const leavingPeople=state.view==='people'&&Boolean(button.dataset.person);if(primaryNavigation){state.globalQuery='';state.peopleQuery='';state.workQuery='';}else if(fromGlobalSearch||leavingPeople){state.globalQuery='';}state.profile='overview';if(button.dataset.scope){state.scope=button.dataset.scope;state.peopleLimit=120;contextKey='';state.graphPage=0;state.work=null;ensurePersonInContext();}if(button.hasAttribute('data-context-reset')){state.scope='all';state.relationMode='all';state.peopleLimit=120;contextKey='';state.graphPage=0;}if(button.hasAttribute('data-relation-all')){state.relationMode='all';state.peopleLimit=120;contextKey='';state.graphPage=0;ensurePersonInContext();}if(button.dataset.person){state.person=button.dataset.person;state.graphPage=0;const dialog=document.getElementById('evidence-dialog');if(dialog.open)dialog.close();}if(button.dataset.view){state.view=button.dataset.view;state.work=null;}if(button.dataset.profile)state.profile=button.dataset.profile;if(button.dataset.work){state.work=button.dataset.work;state.view='works';}if(button.hasAttribute('data-work-back')){state.work=null;state.view='works';}if(button.dataset.workFilter)state.workFilter=button.dataset.workFilter;if(button.dataset.family)state.family=button.dataset.family;if(button.dataset.place)state.place=button.dataset.place;if(button.dataset.peopleKind){state.peopleKind=button.dataset.peopleKind;state.peopleLimit=120;}if(button.hasAttribute('data-people-more'))state.peopleLimit+=120;if(button.dataset.graphPage!==undefined)state.graphPage=Number(button.dataset.graphPage);document.getElementById('search-results').hidden=true;syncUrl();render();if(!button.hasAttribute('data-people-more'))scrollPageTop();});
document.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target.matches('.graph-node')){event.preventDefault();event.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('change',event=>{if(event.target.id==='relation-scope'){state.relationMode=event.target.value;state.peopleLimit=120;contextKey='';state.graphPage=0;state.work=null;ensurePersonInContext();syncUrl();render();}});
function renderGlobalSearch(){const started=performance.now();refreshContext();const q=normalizeName(state.globalQuery),container=document.getElementById('search-results');container.hidden=!q;if(!q){container.innerHTML='';document.documentElement.dataset.lastSearchMs=(performance.now()-started).toFixed(1);return;}const foundPeople=[...contextPeople].map(id=>people.get(id)).filter(p=>searchTextByPerson.get(p.id).includes(q)).sort((a,b)=>personSearchRank(a,q)-personSearchRank(b,q)||byConnections(a,b)).slice(0,12);const foundWorks=D.works.filter(w=>(!contextWorkIds||contextWorkIds.has(w.id))&&w.title.toLocaleLowerCase('ru').includes(q)).slice(0,8);container.innerHTML=(foundPeople.length?`<p class="search-heading">Персонажи</p>${foundPeople.map(p=>personAnchor(p)).join('')}`:'')+(foundWorks.length?`<p class="search-heading">Произведения</p>${foundWorks.map(w=>workAnchor(w)).join('')}`:'')||'<p>В выбранном контексте ничего не найдено.</p>';document.documentElement.dataset.lastSearchMs=(performance.now()-started).toFixed(1);}
document.getElementById('search').addEventListener('input',event=>{state.globalQuery=event.target.value.trim();clearTimeout(searchRenderTimer);searchRenderTimer=setTimeout(renderGlobalSearch,45);});
document.addEventListener('input',event=>{if(event.target.id==='work-search'){state.workQuery=event.target.value;document.getElementById('work-results').innerHTML=workTable(state.workQuery);scheduleSearchUrl();}if(event.target.id==='scope-search'){const q=normalizeName(event.target.value);document.querySelectorAll('[data-scope-option]').forEach(option=>option.hidden=Boolean(q)&&!option.dataset.scopeName.includes(q));document.querySelectorAll('[data-scope-group]').forEach(group=>{if(q)group.open=true;});}});
document.addEventListener('keydown',event=>{if(event.key==='Escape')document.getElementById('search-results').hidden=true;});
document.getElementById('evidence-dialog').addEventListener('click',event=>{if(event.target===event.currentTarget&&event.offsetX<0)event.currentTarget.close();});
document.getElementById('about').addEventListener('click',()=>{document.getElementById('evidence-title').textContent='О литературном атласе';document.getElementById('evidence-content').innerHTML=`<p>Атлас объединяет персонажей десяти томов Фазиля Искандера и показывает, в каких произведениях они появляются.</p><p>Откройте героя, чтобы увидеть его родственников, друзей, противников и собеседников. Из каждой связи можно перейти к цитате из книги.</p><p>Пунктиром обозначены события и связи, переданные со слов персонажа. Описания и цитаты могут раскрывать сюжет.</p>`;document.getElementById('evidence-dialog').showModal();});
window.addEventListener('popstate',()=>{readRoute();render();scrollPageTop();});
families.chik={name:'Семья Чика',nodes:{father_sandro:[90,45],wife_habug:[300,45],persian_consul:[690,45],sandro:[70,180],kyzym:[260,180],chik_mother:[450,180],chik_aunt_husband:[670,180],chik_father:[450,310],chik_aunt:[680,310],chik_older_brother:[240,445],chik:[450,445],chik_sister:[670,445]}};
readRoute();syncUrl(true);render();requestAnimationFrame(scrollPageTop);
